import{_ as t,C as n,o as s,c as i,E as o,a2 as r}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"Open-source Engineering Daily 003 — Manager Orchestration and Handoffs Encode Different Ownership Models","description":"","frontmatter":{"title":"Open-source Engineering Daily 003 — Manager Orchestration and Handoffs Encode Different Ownership Models","date":"2026-08-02","column":"open-source-engineering","category":"daily","summary":"OpenAI Agents SDK distinguishes manager-style specialist calls from handoffs that transfer active control, showing that multi-agent design must model ownership and authority rather than treating every delegation as the same tool call.","sources":["OpenAI Agents SDK agent orchestration documentation","OpenAI Agents SDK handoffs, guardrails, and tracing documentation"],"outline":"deep","cover":"/assets/covers/manager-handoff-ownership-models-cover-v2.jpg"},"headers":[],"relativePath":"en/engineering/2026-08-02-manager-handoff-ownership-models.md","filePath":"en/engineering/2026-08-02-manager-handoff-ownership-models.md","lastUpdated":1787407830000}'),l={name:"en/engineering/2026-08-02-manager-handoff-ownership-models.md"};function p(h,e,d,c,u,g){const a=n("ArticleCover");return s(),i("div",null,[o(a,{image:"/assets/covers/manager-handoff-ownership-models-cover-v2.jpg",kicker:"Open-source Engineering · Daily 003",title:"Manager Orchestration and Handoffs Encode Different Ownership Models",summary:"Calling a specialist while retaining control is not the same operation as transferring the active conversation and responsibility.",version:"ED003",status:"Production Test V1 · 2026-08-02",languageHref:"/zh/engineering/2026-08-02-manager-handoff-ownership-models",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>The OpenAI Agents SDK presents two common multi-agent composition patterns.</p><p>In the <strong>manager pattern</strong>, one Agent retains the user-facing conversation and calls specialist Agents as tools. The manager combines their outputs and remains responsible for the final answer.</p><p>In the <strong>handoff pattern</strong>, a triage or current Agent transfers control to a specialist. The specialist becomes the active Agent, receives conversation history unless it is filtered, and produces the downstream response.</p><p>The Research Center judgment is:</p><blockquote><p>Manager calls and handoffs are not stylistic alternatives. They encode different ownership, authority, context, guardrail, and completion models. A reliable multi-agent runtime must record which one occurred.</p></blockquote><p>Treating both as generic “delegation” hides the most important operational fact: who owns the work after the boundary is crossed.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="selected-primary-material" tabindex="-1">Selected primary material <a class="header-anchor" href="#selected-primary-material" aria-label="Permalink to &quot;Selected primary material&quot;">​</a></h3><ol><li><strong>OpenAI Agents SDK Agent orchestration and Agents documentation</strong> — selected because it explicitly contrasts Agents-as-tools with handoffs and explains when a central manager should retain control.</li><li><strong>Handoffs documentation</strong> — selected because it defines transfer behavior, history forwarding, input filters, handoff metadata, and the fact that handoffs remain inside one run.</li><li><strong>Guardrails documentation</strong> — selected because it exposes different validation boundaries for initial input, final output, function tools, hosted tools, and handoffs.</li><li><strong>Tracing documentation</strong> — selected because it records Agent spans, generations, function calls, guardrails, and handoffs as distinct runtime events.</li></ol><p>These documents define SDK behavior. The architecture judgment below generalizes from the documented mechanisms; it is not a claim that one SDK pattern is universally best.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-a-manager-retains-conversational-and-completion-ownership" tabindex="-1">1. A manager retains conversational and completion ownership <a class="header-anchor" href="#_1-a-manager-retains-conversational-and-completion-ownership" aria-label="Permalink to &quot;1. A manager retains conversational and completion ownership&quot;">​</a></h3><p>When a specialist is exposed through <code>Agent.as_tool()</code>, the manager invokes it for a bounded subtask. The specialist returns a result to the manager. The manager remains the active Agent, chooses whether more work is needed, composes the response, and owns the final user-facing output.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Manager Agent</span></span>
<span class="line"><span>  ├── call Specialist A as tool</span></span>
<span class="line"><span>  ├── call Specialist B as tool</span></span>
<span class="line"><span>  └── integrate and answer</span></span></code></pre></div><p>This pattern is appropriate when one component must enforce a common policy, combine multiple findings, preserve one voice, or remain accountable for completion.</p><h3 id="_2-a-handoff-transfers-the-active-role" tabindex="-1">2. A handoff transfers the active role <a class="header-anchor" href="#_2-a-handoff-transfers-the-active-role" aria-label="Permalink to &quot;2. A handoff transfers the active role&quot;">​</a></h3><p>A handoff is presented to the model as a transfer operation such as <code>transfer_to_refund_agent</code>. When invoked, the receiving Agent takes over the conversation. It normally receives prior conversation history, although input filters or nested-history settings can alter what is forwarded.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Triage Agent</span></span>
<span class="line"><span>  ↓ handoff event</span></span>
<span class="line"><span>Specialist Agent becomes active</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Specialist responds and owns the next turn</span></span></code></pre></div><p>A handoff therefore changes the active instruction set, available tools, contextual view, and responsibility for the final output.</p><h3 id="_3-validation-boundaries-differ" tabindex="-1">3. Validation boundaries differ <a class="header-anchor" href="#_3-validation-boundaries-differ" aria-label="Permalink to &quot;3. Validation boundaries differ&quot;">​</a></h3><p>The SDK documentation highlights several boundaries that matter operationally:</p><ul><li>input guardrails apply to the first Agent in a chain;</li><li>output guardrails apply to the Agent producing the final output;</li><li>function-tool guardrails can run around every function-tool invocation;</li><li>handoffs use the handoff pipeline rather than the normal function-tool guardrail pipeline;</li><li>hosted and built-in execution tools have their own safety and control considerations.</li></ul><p>A system that assumes “every delegation is covered by the same guardrail” can therefore create unprotected transitions.</p><h3 id="_4-tracing-treats-the-operations-as-distinct-events" tabindex="-1">4. Tracing treats the operations as distinct events <a class="header-anchor" href="#_4-tracing-treats-the-operations-as-distinct-events" aria-label="Permalink to &quot;4. Tracing treats the operations as distinct events&quot;">​</a></h3><p>The Agents SDK records function calls and handoffs in different trace spans. This is not merely an observability convenience. It reflects different runtime semantics: a function result returns to the caller, while a handoff changes the active Agent path.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="ownership-comparison" tabindex="-1">Ownership comparison <a class="header-anchor" href="#ownership-comparison" aria-label="Permalink to &quot;Ownership comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimension</th><th>Manager / Agent as tool</th><th>Handoff</th></tr></thead><tbody><tr><td>Active conversational owner</td><td>Manager remains active</td><td>Specialist becomes active</td></tr><tr><td>Specialist scope</td><td>Bounded subtask</td><td>Ongoing turn or workflow responsibility</td></tr><tr><td>Final response owner</td><td>Manager</td><td>Receiving specialist</td></tr><tr><td>Context flow</td><td>Structured call input plus local context chosen by manager</td><td>Conversation history by default, configurable through filters</td></tr><tr><td>Shared policy point</td><td>Central manager can consistently apply policy</td><td>Policy must remain valid across receiving Agent and transition</td></tr><tr><td>Best fit</td><td>Research, calculation, review, bounded expertise, aggregation</td><td>Triage, domain transfer, direct specialist interaction</td></tr><tr><td>Main risk</td><td>Manager becomes bottleneck or distorts specialist output</td><td>Ownership transfer becomes implicit or loses required context</td></tr></tbody></table><p><em>Table: joinwell52 Research Center synthesis from OpenAI Agents SDK documentation.</em></p><h3 id="delegation-needs-an-explicit-operation-type" tabindex="-1">Delegation needs an explicit operation type <a class="header-anchor" href="#delegation-needs-an-explicit-operation-type" aria-label="Permalink to &quot;Delegation needs an explicit operation type&quot;">​</a></h3><p>A multi-agent task record should not contain only <code>from</code> and <code>to</code>. It should state why the other Agent is involved and whether responsibility changes.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">delegation_event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">consult | assign_subtask | handoff | escalate | return</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  from_actor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  to_actor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_snapshot_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  context_package_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  expected_output_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_owner_before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_owner_after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  guardrail_profile_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>This structure prevents a “specialist call” from silently becoming a transfer of authority.</p><h3 id="a-handoff-is-not-the-same-as-creating-a-child-task" tabindex="-1">A handoff is not the same as creating a child task <a class="header-anchor" href="#a-handoff-is-not-the-same-as-creating-a-child-task" aria-label="Permalink to &quot;A handoff is not the same as creating a child task&quot;">​</a></h3><p>A child task can be executed asynchronously while the parent owner retains responsibility for integration and closure. A handoff normally transfers the active conversational role. These can be combined, but they should not be conflated.</p><p>For example:</p><ul><li>PM asks QA for a bounded verification report: <strong>subtask/consult</strong>, PM retains final ownership.</li><li>ADMIN transfers an operational incident to OPS with authority to manage recovery: <strong>handoff or assignment</strong>, ownership may change.</li><li>QA finds a policy exception and returns it to ADMIN: <strong>escalation</strong>, decision authority changes but execution ownership may remain.</li></ul><p>The runtime must represent these distinctions rather than inferring them from natural-language messages.</p><h3 id="context-transfer-is-a-governed-package" tabindex="-1">Context transfer is a governed package <a class="header-anchor" href="#context-transfer-is-a-governed-package" aria-label="Permalink to &quot;Context transfer is a governed package&quot;">​</a></h3><p>Forwarding the entire conversation is convenient but may expose unnecessary data, stale instructions, or untrusted tool outputs. A production handoff should construct a context package containing:</p><ul><li>task identity and objective;</li><li>accepted facts and evidence references;</li><li>unresolved questions;</li><li>authority and policy snapshot;</li><li>allowed tools and data scope;</li><li>expected output contract;</li><li>explicit exclusions;</li><li>return or escalation condition.</li></ul><p>The receiving Agent should not have to reconstruct authority from a long transcript.</p><h3 id="completion-must-follow-ownership" tabindex="-1">Completion must follow ownership <a class="header-anchor" href="#completion-must-follow-ownership" aria-label="Permalink to &quot;Completion must follow ownership&quot;">​</a></h3><p>When a manager retains ownership, a specialist’s success means “subtask result returned,” not “parent work completed.” When a handoff transfers ownership, completion gates, output validation, and release authority must move or be reattached explicitly.</p><p>This is the difference between an orchestration graph that merely routes text and one that governs work.</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>This note does not edit TMPA publications. It supplies research input for separating Message Transfer, Work Assignment, Authority Transfer, Custody, and Completion Ownership. A deterministic reconstruction should show not only who acted, but whether the interaction was a consultation, subtask, handoff, escalation, or return.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>Digital Employee Position definitions should state:</p><ul><li>which work can be accepted directly;</li><li>which specialists may be consulted;</li><li>which work may be handed off;</li><li>which authority can transfer;</li><li>who remains accountable for final completion;</li><li>what context and evidence must accompany the transfer.</li></ul><p>A Digital Employee platform should display current work owner separately from contributors.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu’s PM pattern is naturally close to manager orchestration: PM decomposes work, invokes DEV/QA/OPS, integrates evidence, and reports to ADMIN. This should remain the default for bounded specialist work.</p><p>Handoff should be reserved for explicit responsibility transfer. The runtime should add a typed delegation event and show:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>current owner</span></span>
<span class="line"><span>contributors</span></span>
<span class="line"><span>pending subtask owners</span></span>
<span class="line"><span>decision authority</span></span>
<span class="line"><span>release authority</span></span>
<span class="line"><span>last handoff or return event</span></span></code></pre></div><p>FCoP lifecycle transitions can preserve custody, but the product should not infer orchestration semantics solely from file movement. The task metadata and runtime event should state the operation type.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>Add typed delegation semantics to the Research OS and CodeFlowMu runtime models.</li><li>Define a minimal Context Package for handoff and escalation.</li><li>Test manager, parallel subtask, sequential handoff, and return-to-manager patterns on the same development task.</li><li>Verify guardrail coverage at every boundary, including hosted tools and handoffs.</li><li>Compare trace evidence with FCoP lifecycle events and reports.</li><li>Define which Agent may declare parent completion after a handoff chain.</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>OpenAI Agents SDK, <strong>Agent orchestration</strong>: <a href="https://openai.github.io/openai-agents-python/multi_agent/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/multi_agent/</a></li><li>OpenAI Agents SDK, <strong>Agents</strong>: <a href="https://openai.github.io/openai-agents-python/agents/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/agents/</a></li><li>OpenAI Agents SDK, <strong>Handoffs</strong>: <a href="https://openai.github.io/openai-agents-python/handoffs/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/handoffs/</a></li><li>OpenAI Agents SDK, <strong>Guardrails</strong>: <a href="https://openai.github.io/openai-agents-python/guardrails/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/guardrails/</a></li><li>OpenAI Agents SDK, <strong>Tracing</strong>: <a href="https://openai.github.io/openai-agents-python/tracing/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/tracing/</a></li></ol>`,62))])}const k=t(l,[["render",p]]);export{m as __pageData,k as default};
